const sent=fs.readFileSync(root+'../downloads/tampered-STORED-S4.zip'),auditStart=new Date().toISOString();const audit=await fetch('http://127.0.0.1:9866/api/backups/full/restore',{method:'POST',headers:{Origin:'http://127.0.0.1:9866','Content-Type':'application/zip'},body:sent});const text=await audit.text(),body=JSON.parse(text);fs.writeFileSync(root+'S4-audited-backend-rejection.json',JSON.stringify({channel:'Node fetch, actual backend HTTP response, no CDP Network.getResponseBody',timeStart:auditStart,timeEnd:new Date().toISOString(),url:'http://127.0.0.1:9866/api/backups/full/restore',origin:'http://127.0.0.1:9866',requestSHA256:require('crypto').createHash('sha256').update(sent).digest('hex'),status:audit.status,headers:Object.fromEntries(audit.headers),rawBody:text,body,uiStatus:status,uiFeedback},null,2));await check('S4 audited backend400',audit.status,400);await check('S4 audited genuine PDF hash error',body.message,'RESTORE_PDF_HASH_MISMATCH');await check('S4 audited refusal category',body.error,'RESTORE_REJECTED');
